from google.api_core import retry as retries
from google.cloud import secretmanager
from pydantic import BaseModel

from datahub.secret.secret_store import SecretStore

logger = logging.getLogger(__name__)


class GcpSecretManagerStoreConfig(BaseModel):
    project_id: str
    prefix: str = ""
    cache_ttl: int = 60


# SecretStore implementation that fetches secret values from Google Cloud Secret Manager.
class GcpSecretManagerStore(SecretStore):
    def __init__(self, config: GcpSecretManagerStoreConfig):
        self.config = config
        self.project_id = config.project_id
        self.prefix = config.prefix
        self.client = secretmanager.SecretManagerServiceClient()

    def get_secret_values(self, secret_names: List[str]) -> Dict[str, Optional[str]]:
        values: Dict[str, Optional[str]] = {}
        for secret_name in secret_names:
            values[secret_name] = self._fetch_secret(secret_name)
        return values

    def get_secret_value(self, secret_name: str) -> Optional[str]:
        return self._fetch_secret(secret_name)

    def _fetch_secret(self, secret_name: str) -> Optional[str]:
        name = (
            f"projects/{self.project_id}/secrets/"
            f"{self.prefix}{secret_name}/versions/latest"
        )
        try:
            response = self.client.access_secret_version(
                request={"name": name},
                retry=retries.Retry(),
            )
            return response.payload.data.decode("UTF-8")
        except Exception:
            logger.debug(
                f"Unable to fetch secret '{name}' from GCP Secret Manager.",
                exc_info=True,
            )
            return None

    def get_id(self) -> str:
        return "gcp-sm"

    def close(self) -> None:
        return

    @classmethod
    def create(cls, config: Any) -> "GcpSecretManagerStore":
        config = GcpSecretManagerStoreConfig.model_validate(config)
        return cls(config)
